import { spreadsheetValue } from "./safety.ts";

// RFC 4180: fields containing a delimiter, quote or line break are quoted, with embedded quotes doubled.
function csvField(value: string): string {
  return /[",\r\n]/.test(value) ? '"' + value.replaceAll('"', '""') + '"' : value;
}

export function csvRecord(values: string[]): string {
  const cells = values.map(value => csvField(spreadsheetValue(value)));
  return cells.join(",") + "\r\n";
}
EOF
